//! Exact one- and two-electron integrals over contracted Cartesian Gaussians.
//!
//! All integrals use the McMurchie–Davidson scheme: the product of two
//! Cartesian Gaussians `x^i e^{-a(x-A)^2} · x^j e^{-b(x-B)^2}` is expanded in
//! Hermite Gaussians centred at the Gaussian product centre `P = (aA + bB)/p`,
//!
//! ```text
//! G_i G_j = Σ_t E^{ij}_t Λ_t(x; p, P_x),   p = a + b,
//! ```
//!
//! with the coefficients generated by the recursions
//!
//! ```text
//! E^{00}_0     = exp(−ab/p · (A−B)²)
//! E^{i+1,j}_t  = E^{ij}_{t−1}/(2p) + X_PA E^{ij}_t + (t+1) E^{ij}_{t+1}
//! E^{i,j+1}_t  = E^{ij}_{t−1}/(2p) + X_PB E^{ij}_t + (t+1) E^{ij}_{t+1}
//! ```
//!
//! Coulomb-type integrals use the Hermite integrals `R^n_{tuv}` built from the
//! Boys function `F_n`.  These formulas are exact for any angular momentum, so
//! s, p, d, … functions are all handled by the same code.
//!
//! The contraction coefficients of a [`BasisFunction`] already contain the
//! primitive normalisation, so every contracted integral is the plain
//! coefficient-weighted sum of raw primitive integrals.

use std::f64::consts::PI;

use oxiphysics_core::numerics::boys_fn;

use super::types::BasisFunction;

/// Hermite expansion coefficient `E^{ij}_t` for one Cartesian direction.
///
/// `ab_x` is the component `A_x − B_x` of the vector between the two centres,
/// `a` and `b` are the primitive exponents.
fn hermite_e(i: i32, j: i32, t: i32, ab_x: f64, a: f64, b: f64) -> f64 {
    if t < 0 || t > i + j || i < 0 || j < 0 {
        return 0.0;
    }
    let p = a + b;
    let mu = a * b / p;
    if i == 0 && j == 0 {
        // t == 0 here because t ≤ i + j.
        return (-mu * ab_x * ab_x).exp();
    }
    if j == 0 {
        // X_PA = −(b/p)(A − B)
        let x_pa = -b / p * ab_x;
        hermite_e(i - 1, j, t - 1, ab_x, a, b) / (2.0 * p)
            + x_pa * hermite_e(i - 1, j, t, ab_x, a, b)
            + f64::from(t + 1) * hermite_e(i - 1, j, t + 1, ab_x, a, b)
    } else {
        // X_PB = (a/p)(A − B)
        let x_pb = a / p * ab_x;
        hermite_e(i, j - 1, t - 1, ab_x, a, b) / (2.0 * p)
            + x_pb * hermite_e(i, j - 1, t, ab_x, a, b)
            + f64::from(t + 1) * hermite_e(i, j - 1, t + 1, ab_x, a, b)
    }
}

/// Table of Hermite Coulomb integrals `R^0_{tuv}` for `t ≤ t_max`, `u ≤ u_max`,
/// `v ≤ v_max`, evaluated for exponent `p` and separation `pc = P − C`.
struct HermiteCoulomb {
    u_dim: usize,
    v_dim: usize,
    values: Vec<f64>,
}

impl HermiteCoulomb {
    fn new(t_max: usize, u_max: usize, v_max: usize, p: f64, pc: [f64; 3]) -> Self {
        let n_max = t_max + u_max + v_max;
        let r2 = pc[0] * pc[0] + pc[1] * pc[1] + pc[2] * pc[2];
        let boys = boys_fn(p * r2, n_max);
        let t_dim = t_max + 1;
        let u_dim = u_max + 1;
        let v_dim = v_max + 1;
        // r[n][t][u][v], filled for decreasing n so that R^{n+1} is available.
        let block = t_dim * u_dim * v_dim;
        let idx = |t: usize, u: usize, v: usize| (t * u_dim + u) * v_dim + v;
        let mut next = vec![0.0_f64; block];
        let mut current = vec![0.0_f64; block];
        let mut minus_two_p_pow = (-2.0 * p).powi(n_max as i32);
        for n in (0..=n_max).rev() {
            let order = n_max - n;
            for t in 0..t_dim {
                for u in 0..u_dim {
                    for v in 0..v_dim {
                        if t + u + v > order {
                            current[idx(t, u, v)] = 0.0;
                            continue;
                        }
                        let value = if t == 0 && u == 0 && v == 0 {
                            minus_two_p_pow * boys[n]
                        } else if t > 0 {
                            let mut acc = pc[0] * next[idx(t - 1, u, v)];
                            if t > 1 {
                                acc += (t - 1) as f64 * next[idx(t - 2, u, v)];
                            }
                            acc
                        } else if u > 0 {
                            let mut acc = pc[1] * next[idx(t, u - 1, v)];
                            if u > 1 {
                                acc += (u - 1) as f64 * next[idx(t, u - 2, v)];
                            }
                            acc
                        } else {
                            let mut acc = pc[2] * next[idx(t, u, v - 1)];
                            if v > 1 {
                                acc += (v - 1) as f64 * next[idx(t, u, v - 2)];
                            }
                            acc
                        };
                        current[idx(t, u, v)] = value;
                    }
                }
            }
            std::mem::swap(&mut next, &mut current);
            minus_two_p_pow /= -2.0 * p;
        }
        // After the last swap `next` holds R^0.
        Self {
            u_dim,
            v_dim,
            values: next,
        }
    }

    fn get(&self, t: usize, u: usize, v: usize) -> f64 {
        self.values[(t * self.u_dim + u) * self.v_dim + v]
    }
}

/// Hermite expansion coefficients of one primitive pair in all three directions:
/// `coeffs[k][t] = E^{l_k^a, l_k^b}_t`.
struct PairExpansion {
    p: f64,
    centre: [f64; 3],
    coeffs: [Vec<f64>; 3],
}

impl PairExpansion {
    fn new(
        a: f64,
        la: [u8; 3],
        centre_a: [f64; 3],
        b: f64,
        lb: [u8; 3],
        centre_b: [f64; 3],
    ) -> Self {
        let p = a + b;
        let centre = [
            (a * centre_a[0] + b * centre_b[0]) / p,
            (a * centre_a[1] + b * centre_b[1]) / p,
            (a * centre_a[2] + b * centre_b[2]) / p,
        ];
        let coeffs = [0usize, 1, 2].map(|k| {
            let i = i32::from(la[k]);
            let j = i32::from(lb[k]);
            let ab = centre_a[k] - centre_b[k];
            (0..=(i + j))
                .map(|t| hermite_e(i, j, t, ab, a, b))
                .collect::<Vec<f64>>()
        });
        Self { p, centre, coeffs }
    }
}

/// `(2l − 1)!!` with `(−1)!! = 1`.
pub(crate) fn odd_double_factorial(l: u8) -> f64 {
    let mut acc = 1.0;
    let mut k = 2 * i32::from(l) - 1;
    while k > 1 {
        acc *= f64::from(k);
        k -= 2;
    }
    acc
}

/// Normalisation constant of the primitive `x^l y^m z^n exp(−α r²)`.
pub(crate) fn primitive_normalisation(alpha: f64, cartesian: [u8; 3]) -> f64 {
    let total = cartesian.iter().map(|&l| u32::from(l)).sum::<u32>();
    let denom: f64 = cartesian.iter().map(|&l| odd_double_factorial(l)).product();
    (2.0 * alpha / PI).powf(0.75) * (4.0 * alpha).powf(f64::from(total) / 2.0) / denom.sqrt()
}

/// Overlap of two primitives (raw, unnormalised).
fn primitive_overlap(
    a: f64,
    la: [u8; 3],
    centre_a: [f64; 3],
    b: f64,
    lb: [u8; 3],
    centre_b: [f64; 3],
) -> f64 {
    let p = a + b;
    let mut s = (PI / p).powf(1.5);
    for k in 0..3 {
        s *= hermite_e(
            i32::from(la[k]),
            i32::from(lb[k]),
            0,
            centre_a[k] - centre_b[k],
            a,
            b,
        );
    }
    s
}

/// Kinetic-energy integral `⟨a| −½∇² |b⟩` of two primitives, from the action of
/// the Laplacian on the ket: `∂²/∂x² x^j e^{−bx²} = j(j−1)x^{j−2} − 2b(2j+1)x^j + 4b² x^{j+2}`.
fn primitive_kinetic(
    a: f64,
    la: [u8; 3],
    centre_a: [f64; 3],
    b: f64,
    lb: [u8; 3],
    centre_b: [f64; 3],
) -> f64 {
    let total_b: f64 = lb.iter().map(|&l| f64::from(l)).sum();
    let mut t = b * (2.0 * total_b + 3.0) * primitive_overlap(a, la, centre_a, b, lb, centre_b);
    for k in 0..3 {
        let mut up = lb;
        up[k] += 2;
        t -= 2.0 * b * b * primitive_overlap(a, la, centre_a, b, up, centre_b);
        if lb[k] >= 2 {
            let mut down = lb;
            down[k] -= 2;
            let lk = f64::from(lb[k]);
            t -= 0.5 * lk * (lk - 1.0) * primitive_overlap(a, la, centre_a, b, down, centre_b);
        }
    }
    t
}

/// `Σ_{tuv} E_t E_u E_v R_{tuv}` for one primitive pair and a Hermite table.
fn contract_pair_with_coulomb(pair: &PairExpansion, table: &HermiteCoulomb) -> f64 {
    let mut acc = 0.0;
    for (t, &ex) in pair.coeffs[0].iter().enumerate() {
        for (u, &ey) in pair.coeffs[1].iter().enumerate() {
            for (v, &ez) in pair.coeffs[2].iter().enumerate() {
                acc += ex * ey * ez * table.get(t, u, v);
            }
        }
    }
    acc
}

/// Overlap integral `⟨φ_a|φ_b⟩` of two contracted Cartesian Gaussians.
pub fn overlap_integral(bf_a: &BasisFunction, bf_b: &BasisFunction) -> f64 {
    let mut s = 0.0;
    for (&a, &ca) in bf_a.exponents.iter().zip(bf_a.coefficients.iter()) {
        for (&b, &cb) in bf_b.exponents.iter().zip(bf_b.coefficients.iter()) {
            s += ca
                * cb
                * primitive_overlap(
                    a,
                    bf_a.cartesian,
                    bf_a.center,
                    b,
                    bf_b.cartesian,
                    bf_b.center,
                );
        }
    }
    s
}

/// Kinetic-energy integral `⟨φ_a| −½∇² |φ_b⟩` of two contracted Cartesian Gaussians.
pub fn kinetic_integral(bf_a: &BasisFunction, bf_b: &BasisFunction) -> f64 {
    let mut t = 0.0;
    for (&a, &ca) in bf_a.exponents.iter().zip(bf_a.coefficients.iter()) {
        for (&b, &cb) in bf_b.exponents.iter().zip(bf_b.coefficients.iter()) {
            t += ca
                * cb
                * primitive_kinetic(
                    a,
                    bf_a.cartesian,
                    bf_a.center,
                    b,
                    bf_b.cartesian,
                    bf_b.center,
                );
        }
    }
    t
}

/// Nuclear-attraction integral `⟨φ_a| −Z/|r − C| |φ_b⟩` for a point charge `Z`
/// at `c` \[Bohr\].
pub fn nuclear_attraction_integral(
    bf_a: &BasisFunction,
    bf_b: &BasisFunction,
    z: f64,
    c: [f64; 3],
) -> f64 {
    let mut v = 0.0;
    for (&a, &ca) in bf_a.exponents.iter().zip(bf_a.coefficients.iter()) {
        for (&b, &cb) in bf_b.exponents.iter().zip(bf_b.coefficients.iter()) {
            let pair = PairExpansion::new(
                a,
                bf_a.cartesian,
                bf_a.center,
                b,
                bf_b.cartesian,
                bf_b.center,
            );
            let pc = [
                pair.centre[0] - c[0],
                pair.centre[1] - c[1],
                pair.centre[2] - c[2],
            ];
            let table = HermiteCoulomb::new(
                pair.coeffs[0].len() - 1,
                pair.coeffs[1].len() - 1,
                pair.coeffs[2].len() - 1,
                pair.p,
                pc,
            );
            v += ca * cb * 2.0 * PI / pair.p * contract_pair_with_coulomb(&pair, &table);
        }
    }
    -z * v
}

/// Electron-repulsion integral `(ab|cd)` in chemists' notation:
/// `∫∫ φ_a(1) φ_b(1) |r₁ − r₂|⁻¹ φ_c(2) φ_d(2)`.
pub fn electron_repulsion_integral(
    bf_a: &BasisFunction,
    bf_b: &BasisFunction,
    bf_c: &BasisFunction,
    bf_d: &BasisFunction,
) -> f64 {
    let bra: Vec<(f64, PairExpansion)> = primitive_pairs(bf_a, bf_b);
    let ket: Vec<(f64, PairExpansion)> = primitive_pairs(bf_c, bf_d);
    let mut val = 0.0;
    for (c_bra, pb) in &bra {
        let t_bra = pb.coeffs[0].len() - 1;
        let u_bra = pb.coeffs[1].len() - 1;
        let v_bra = pb.coeffs[2].len() - 1;
        for (c_ket, pk) in &ket {
            let t_ket = pk.coeffs[0].len() - 1;
            let u_ket = pk.coeffs[1].len() - 1;
            let v_ket = pk.coeffs[2].len() - 1;
            let p = pb.p;
            let q = pk.p;
            let alpha = p * q / (p + q);
            let pq = [
                pb.centre[0] - pk.centre[0],
                pb.centre[1] - pk.centre[1],
                pb.centre[2] - pk.centre[2],
            ];
            let table = HermiteCoulomb::new(t_bra + t_ket, u_bra + u_ket, v_bra + v_ket, alpha, pq);
            let mut acc = 0.0;
            for (t, &ex) in pb.coeffs[0].iter().enumerate() {
                for (u, &ey) in pb.coeffs[1].iter().enumerate() {
                    for (v, &ez) in pb.coeffs[2].iter().enumerate() {
                        let e_bra = ex * ey * ez;
                        if e_bra == 0.0 {
                            continue;
                        }
                        for (tau, &fx) in pk.coeffs[0].iter().enumerate() {
                            for (nu, &fy) in pk.coeffs[1].iter().enumerate() {
                                for (phi, &fz) in pk.coeffs[2].iter().enumerate() {
                                    let sign = if (tau + nu + phi) % 2 == 0 { 1.0 } else { -1.0 };
                                    acc += e_bra
                                        * sign
                                        * fx
                                        * fy
                                        * fz
                                        * table.get(t + tau, u + nu, v + phi);
                                }
                            }
                        }
                    }
                }
            }
            let pre = 2.0 * PI.powf(2.5) / (p * q * (p + q).sqrt());
            val += c_bra * c_ket * pre * acc;
        }
    }
    val
}

/// All primitive pairs of two contracted functions with their combined coefficient.
fn primitive_pairs(bf_a: &BasisFunction, bf_b: &BasisFunction) -> Vec<(f64, PairExpansion)> {
    let mut out = Vec::with_capacity(bf_a.exponents.len() * bf_b.exponents.len());
    for (&a, &ca) in bf_a.exponents.iter().zip(bf_a.coefficients.iter()) {
        for (&b, &cb) in bf_b.exponents.iter().zip(bf_b.coefficients.iter()) {
            out.push((
                ca * cb,
                PairExpansion::new(
                    a,
                    bf_a.cartesian,
                    bf_a.center,
                    b,
                    bf_b.cartesian,
                    bf_b.center,
                ),
            ));
        }
    }
    out
}

/// Dipole integrals `⟨φ_a| (r − O)_k |φ_b⟩` (k = x, y, z) about `origin` \[Bohr\].
///
/// With the Hermite expansion, `∫ x_O Λ_t dx = (π/p)^{1/2} (δ_{t1} + X_PO δ_{t0})`.
pub fn dipole_integral(bf_a: &BasisFunction, bf_b: &BasisFunction, origin: [f64; 3]) -> [f64; 3] {
    let mut d = [0.0_f64; 3];
    for (&a, &ca) in bf_a.exponents.iter().zip(bf_a.coefficients.iter()) {
        for (&b, &cb) in bf_b.exponents.iter().zip(bf_b.coefficients.iter()) {
            let pair = PairExpansion::new(
                a,
                bf_a.cartesian,
                bf_a.center,
                b,
                bf_b.cartesian,
                bf_b.center,
            );
            let pre = ca * cb * (PI / pair.p).powf(1.5);
            let e0 = [pair.coeffs[0][0], pair.coeffs[1][0], pair.coeffs[2][0]];
            for (k, slot) in d.iter_mut().enumerate() {
                let e1 = pair.coeffs[k].get(1).copied().unwrap_or(0.0);
                let moment = e1 + (pair.centre[k] - origin[k]) * e0[k];
                let mut prod = moment;
                for (m, &e0m) in e0.iter().enumerate() {
                    if m != k {
                        prod *= e0m;
                    }
                }
                *slot += pre * prod;
            }
        }
    }
    d
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::quantum_chemistry::sto3g_basis::sto3g_atom_basis;

    /// Crawford's H₂O geometry (bohr) with the STO-3G basis in PySCF AO order
    /// (O 1s, 2s, 2px, 2py, 2pz, H1 1s, H2 1s).
    fn water_basis() -> Vec<BasisFunction> {
        let o = [0.0, -0.143_225_816_552, 0.0];
        let h1 = [1.638_036_840_407, 1.136_548_822_547, 0.0];
        let h2 = [-1.638_036_840_407, 1.136_548_822_547, 0.0];
        let mut basis = sto3g_atom_basis(8, o).expect("O basis");
        basis.extend(sto3g_atom_basis(1, h1).expect("H basis"));
        basis.extend(sto3g_atom_basis(1, h2).expect("H basis"));
        basis
    }

    #[test]
    fn hermite_e_reduces_to_gaussian_product_prefactor() {
        let (a, b, ab) = (0.7, 1.3, 0.9);
        let e = hermite_e(0, 0, 0, ab, a, b);
        assert!((e - (-a * b / (a + b) * ab * ab).exp()).abs() < 1e-15);
        // E^{10}_0 = X_PA E^{00}_0 and E^{10}_1 = E^{00}_0 / (2p)
        let x_pa = -b / (a + b) * ab;
        assert!((hermite_e(1, 0, 0, ab, a, b) - x_pa * e).abs() < 1e-15);
        assert!((hermite_e(1, 0, 1, ab, a, b) - e / (2.0 * (a + b))).abs() < 1e-15);
    }

    #[test]
    fn one_electron_integrals_match_pyscf_for_water() {
        // Reference values: PySCF 2.14, `int1e_ovlp`, `int1e_kin`, `int1e_nuc`, cart=True.
        let basis = water_basis();
        let nuclei = [
            (8.0, [0.0, -0.143_225_816_552, 0.0]),
            (1.0, [1.638_036_840_407, 1.136_548_822_547, 0.0]),
            (1.0, [-1.638_036_840_407, 1.136_548_822_547, 0.0]),
        ];
        let v = |i: usize, j: usize| -> f64 {
            nuclei
                .iter()
                .map(|&(z, c)| nuclear_attraction_integral(&basis[i], &basis[j], z, c))
                .sum()
        };
        let cases: [(usize, usize, f64, f64, f64); 8] = [
            (
                0,
                1,
                0.236_703_936_510_847_6,
                -0.168_010_939_316_492_05,
                -7.410_821_877_331_001,
            ),
            (2, 2, 1.0, 2.528_731_198_194_763_3, -9.987_550_507_419_149),
            (
                0,
                5,
                0.038_405_599_785_760_004,
                -0.008_416_383_544_590_221,
                -1.231_685_872_788_825,
            ),
            (
                2,
                5,
                0.268_438_243_716_425_66,
                0.147_090_913_304_046_44,
                -1.822_241_058_022_548,
            ),
            (
                1,
                5,
                0.386_138_840_478_271_4,
                0.070_517_372_751_014_13,
                -2.977_227_202_971_774,
            ),
            (
                3,
                6,
                0.209_726_941_420_437_88,
                0.114_920_016_354_245_04,
                -1.471_788_274_314_251_9,
            ),
            (
                5,
                6,
                0.181_759_886_298_154_87,
                -0.003_979_868_621_828_917_5,
                -1.067_166_014_696_611_5,
            ),
            (2, 3, 0.0, 0.0, 0.0),
        ];
        for (i, j, s_ref, t_ref, v_ref) in cases {
            let s = overlap_integral(&basis[i], &basis[j]);
            let t = kinetic_integral(&basis[i], &basis[j]);
            let vij = v(i, j);
            assert!((s - s_ref).abs() < 2e-8, "S[{i}][{j}] = {s}, ref {s_ref}");
            assert!((t - t_ref).abs() < 2e-8, "T[{i}][{j}] = {t}, ref {t_ref}");
            assert!(
                (vij - v_ref).abs() < 2e-7,
                "V[{i}][{j}] = {vij}, ref {v_ref}"
            );
            // Hermiticity
            assert!((overlap_integral(&basis[j], &basis[i]) - s).abs() < 1e-13);
            assert!((kinetic_integral(&basis[j], &basis[i]) - t).abs() < 1e-12);
        }
    }

    #[test]
    fn electron_repulsion_integrals_match_pyscf_for_water() {
        // Reference values: PySCF 2.14 `int2e`, cart=True.
        let basis = water_basis();
        let cases: [([usize; 4], f64); 7] = [
            ([0, 0, 0, 0], 4.785_065_404_705_503),
            ([2, 2, 2, 2], 0.880_159_093_375_045_3),
            ([2, 3, 2, 3], 0.047_444_445_118_384_165),
            ([2, 2, 3, 3], 0.785_270_203_138_277_6),
            ([2, 5, 2, 6], -0.013_099_738_777_743_22),
            ([4, 4, 5, 5], 0.436_750_211_441_593_7),
            ([3, 5, 3, 6], 0.038_857_871_090_592_73),
        ];
        for ([a, b, c, d], reference) in cases {
            let g = electron_repulsion_integral(&basis[a], &basis[b], &basis[c], &basis[d]);
            assert!(
                (g - reference).abs() < 2e-8,
                "({a}{b}|{c}{d}) = {g}, ref {reference}"
            );
            // 8-fold permutational symmetry
            let g2 = electron_repulsion_integral(&basis[c], &basis[d], &basis[b], &basis[a]);
            assert!((g - g2).abs() < 1e-12);
        }
    }

    #[test]
    fn dipole_of_p_function_pair_matches_closed_form() {
        // ⟨s|x|p_x⟩ on one centre equals ∫ x² exp(−(a+b)r²) N_s N_p.
        let a = 0.8;
        let b = 1.1;
        let s = BasisFunction::contracted([0.0; 3], [0, 0, 0], &[a], &[1.0]);
        let px = BasisFunction::contracted([0.0; 3], [1, 0, 0], &[b], &[1.0]);
        let d = dipole_integral(&s, &px, [0.0; 3]);
        let g = a + b;
        let expected = s.coefficients[0] * px.coefficients[0] * (PI / g).powf(1.5) / (2.0 * g);
        assert!((d[0] - expected).abs() < 1e-14);
        assert!(d[1].abs() < 1e-15 && d[2].abs() < 1e-15);
    }

    #[test]
    fn primitive_normalisation_gives_unit_self_overlap() {
        for cart in [[0, 0, 0], [1, 0, 0], [0, 1, 1], [2, 0, 0]] {
            let alpha = 0.37;
            let n = primitive_normalisation(alpha, cart);
            let s = n * n * primitive_overlap(alpha, cart, [0.0; 3], alpha, cart, [0.0; 3]);
            assert!((s - 1.0).abs() < 1e-13, "{cart:?}: {s}");
        }
    }
}
